75	    public synchronized void goToEarlierVersion() {
76	        if (canGoToEarlierVersion()) {
77	            // If we are at the current state, but this was not saved yet -> save current state
78	            if (hasChangesNotInHistory()) {
79	                forceAddNextChangeToHistory();
80	                addToHistory();
81	                _historyPosition--;
82	            }
83	
84	            _historyPosition--;
85	            if (_historyPosition >= 0 && _historyPosition < _history.size()) {
86	                loadFromDocument(_history.get(_historyPosition));
87	            }
88	        }
89	    }
