package net.gsantner.markor.util;

import net.gsantner.markor.model.Document;

import org.junit.Test;

import java.io.File;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Reproduces bug: "Save button makes the file not save"
 * 1. new note, 2. type title+content, 3. wait until content propagated into the
 * Document (that is when the save icon becomes enabled), 4. press save, 5. press back.
 */
public class DocumentIoSaveRepoTest {

    private File newNotebookFolder() {
        File dir = new File(System.getProperty("java.io.tmpdir"), "markor-test-" + UUID.randomUUID());
        assertThat(dir.mkdirs()).isTrue();
        return dir;
    }

    /** Emulates DocumentEditFragment.loadDocument() for a new note (history disabled = default) */
    private Document newDocument(File folder) {
        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setFile(new File(folder, "document-" + UUID.randomUUID() + ".md"));
        // history disabled by default -> addToHistory() is a no-op here
        document.forceAddNextChangeToHistory();
        document.addToHistory();
        return document;
    }

    @Test
    public void pressingSaveThenBackCreatesTheNote() {
        File folder = newNotebookFolder();
        Document document = newDocument(folder);

        // 2. user enters title and content
        document.setTitle("MyNote");
        // 3. waited for HISTORY_DELTA -> content got pushed into the document
        document.setContent("Hello content");

        // 4. press save icon
        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();
        File expected = new File(folder, "MyNote.md");
        assertThat(expected.exists()).as("note file created on save").isTrue();
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(expected)).isEqualTo("Hello content");

        // 5. press back -> saves again, must not lose the note
        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();
        assertThat(expected.exists()).isTrue();
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(expected)).isEqualTo("Hello content");
    }

    @Test
    public void backWithoutPressingSaveStillCreatesTheNote() {
        File folder = newNotebookFolder();
        Document document = newDocument(folder);
        document.setTitle("Quick");

        // back pressed before HISTORY_DELTA elapsed: document content still empty
        assertThat(DocumentIO.saveDocument(document, true, "Fast typed")).isTrue();
        File expected = new File(folder, "Quick.md");
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(expected)).isEqualTo("Fast typed");
    }

    @Test
    public void editingAnExistingNoteRenamesAndKeepsContent() {
        File folder = newNotebookFolder();
        File existing = new File(folder, "Old.md");
        assertThat(net.gsantner.opoc.util.FileUtils.writeFile(existing, "old content")).isTrue();

        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setFile(existing);
        document.setTitle("Old");
        document.setContent("old content");
        document.forceAddNextChangeToHistory();
        document.addToHistory();

        // rename + change content
        document.setTitle("New");
        assertThat(DocumentIO.saveDocument(document, true, "new content")).isTrue();

        File renamed = new File(folder, "New.md");
        assertThat(renamed.exists()).isTrue();
        assertThat(existing.exists()).as("old file gone after rename").isFalse();
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(renamed)).isEqualTo("new content");
    }

    @Test
    public void revertingContentBackToAPreviousStateIsPersisted() {
        File folder = newNotebookFolder();
        Document document = newDocument(folder);
        document.setTitle("Revert");

        DocumentIO.saveDocument(document, true, "version A");
        File file = new File(folder, "Revert.md");
        DocumentIO.saveDocument(document, true, "version B");
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(file)).isEqualTo("version B");

        // going back to an already known content must still hit the disk
        DocumentIO.saveDocument(document, true, "version A");
        assertThat(net.gsantner.opoc.util.FileUtils.readTextFileFast(file)).isEqualTo("version A");
    }
}

